import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_04_dp_overview.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_04_policy_evaluation.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_04_policy_iteration_loop.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_04_pi_vi_comparison.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_04_state_space_explosion.png",f=JSON.parse('{"title":"价值是怎样从终点倒着传回来的？一篇看懂动态规划","description":"在网格世界里，终点只在到达时给出奖励，远处状态为什么也能逐渐知道应该往哪里走？答案不是智能体突然拥有了全局视野，而是价值通过贝尔曼更新一层层向外传播。动态规划把一个长期决策问题拆成许多相互连接的小问题，也因此成为理解价值型强化学习最清晰的起点。","frontmatter":{"title":"价值是怎样从终点倒着传回来的？一篇看懂动态规划","description":"在网格世界里，终点只在到达时给出奖励，远处状态为什么也能逐渐知道应该往哪里走？答案不是智能体突然拥有了全局视野，而是价值通过贝尔曼更新一层层向外传播。动态规划把一个长期决策问题拆成许多相互连接的小问题，也因此成为理解价值型强化学习最清晰的起点。","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":15,"source":"2026-08-13/rl_series_04_dynamic_programming.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_04_dp_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-04-dynamic-programming"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"价值是怎样从终点倒着传回来的？一篇看懂动态规划"}],["meta",{"property":"og:description","content":"在网格世界里，终点只在到达时给出奖励，远处状态为什么也能逐渐知道应该往哪里走？答案不是智能体突然拥有了全局视野，而是价值通过贝尔曼更新一层层向外传播。动态规划把一个长期决策问题拆成许多相互连接的小问题，也因此成为理解价值型强化学习最清晰的起点。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-04-dynamic-programming"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_04_dp_overview.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"价值是怎样从终点倒着传回来的？一篇看懂动态规划"}],["meta",{"name":"twitter:description","content":"在网格世界里，终点只在到达时给出奖励，远处状态为什么也能逐渐知道应该往哪里走？答案不是智能体突然拥有了全局视野，而是价值通过贝尔曼更新一层层向外传播。动态规划把一个长期决策问题拆成许多相互连接的小问题，也因此成为理解价值型强化学习最清晰的起点。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_04_dp_overview.png"}]],"prev":{"text":"马尔可夫不是“失忆”：一篇看懂强化学习的数学骨架","link":"/rl/rl-series-03-markov-decision-process"},"next":{"text":"不知道环境模型，也能学会决策？蒙特卡洛方法讲透了","link":"/rl/rl-series-05-monte-carlo"}},"headers":[],"relativePath":"rl/rl-series-04-dynamic-programming.md","filePath":"rl/rl-series-04-dynamic-programming.md","lastUpdated":null}'),p={name:"rl/rl-series-04-dynamic-programming.md"};function d(c,a,_,m,u,b){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="价值是怎样从终点倒着传回来的-一篇看懂动态规划" tabindex="-1">价值是怎样从终点倒着传回来的？一篇看懂动态规划 <a class="header-anchor" href="#价值是怎样从终点倒着传回来的-一篇看懂动态规划" aria-label="Permalink to &quot;价值是怎样从终点倒着传回来的？一篇看懂动态规划&quot;">​</a></h1><p>在网格世界里，终点只在到达时给出奖励，远处状态为什么也能逐渐知道应该往哪里走？答案不是智能体突然拥有了全局视野，而是价值通过贝尔曼更新一层层向外传播。动态规划把一个长期决策问题拆成许多相互连接的小问题，也因此成为理解价值型强化学习最清晰的起点。</p><p><img src="'+l+'" alt="动态规划解决 MDP 总览"></p><h2 id="一、结论先说" tabindex="-1">一、结论先说 <a class="header-anchor" href="#一、结论先说" aria-label="Permalink to &quot;一、结论先说&quot;">​</a></h2><p>动态规划（Dynamic Programming，动态规划）是一类在环境模型已知时求解马尔可夫决策过程（Markov Decision Process，马尔可夫决策过程）的方法。这里的“模型已知”，意味着状态转移概率 $P(s&#39;|s,a)$ 和奖励函数 $R(s,a,s&#39;)$ 可以被查询或计算。</p><p>它解决两类问题：给定策略，计算这套策略有多好，称为策略评估；寻找能够获得更高回报的策略，称为控制。</p><p>策略迭代（Policy Iteration，策略迭代）在“评估策略”和“改进策略”之间循环；价值迭代（Value Iteration，价值迭代）直接反复应用贝尔曼最优更新，在价值收敛后提取贪心策略。</p><p>动态规划不是依靠采样经验学习的典型强化学习算法。它知道完整环境模型，并对所有可能后继状态做期望计算。但它揭示了策略评估、策略改进、自举和贝尔曼备份这些核心结构，后面的蒙特卡洛、时序差分和 Q-learning（Q 学习）都会沿着这套骨架继续发展。</p><h2 id="二、动态规划需要什么前提" tabindex="-1">二、动态规划需要什么前提 <a class="header-anchor" href="#二、动态规划需要什么前提" aria-label="Permalink to &quot;二、动态规划需要什么前提&quot;">​</a></h2><h3 id="_2-1-完整的-mdp-模型" tabindex="-1">2.1 完整的 MDP 模型 <a class="header-anchor" href="#_2-1-完整的-mdp-模型" aria-label="Permalink to &quot;2.1 完整的 MDP 模型&quot;">​</a></h3><p>动态规划需要明确的状态空间 $\\mathcal{S}$、动作空间 $\\mathcal{A}$、转移概率 $P$、奖励函数 $R$ 和折扣因子 $\\gamma$。给定状态与动作，它必须能够枚举或积分所有可能的下一状态，并计算对应概率与奖励。</p><p>这和真实车辆只执行一次动作、观察到一个结果不同。动态规划会做 full backup（完整备份）：把所有可能后继分支都纳入期望，而不是只使用实际采样到的单条转移。</p><h3 id="_2-2-有限状态动作更容易精确求解" tabindex="-1">2.2 有限状态动作更容易精确求解 <a class="header-anchor" href="#_2-2-有限状态动作更容易精确求解" aria-label="Permalink to &quot;2.2 有限状态动作更容易精确求解&quot;">​</a></h3><p>经典表格动态规划通常假设状态和动作有限。每个状态都保存一个价值，每轮更新遍历全部状态和动作。</p><p>当状态是连续高维向量、动作也是连续量时，无法直接枚举全部组合，需要离散化、函数逼近、采样或其他优化方法。深度强化学习之所以使用神经网络，很大程度上就是因为真实问题无法维护一张完整价值表。</p><h3 id="_2-3-马尔可夫状态仍然是基础" tabindex="-1">2.3 马尔可夫状态仍然是基础 <a class="header-anchor" href="#_2-3-马尔可夫状态仍然是基础" aria-label="Permalink to &quot;2.3 马尔可夫状态仍然是基础&quot;">​</a></h3><p>如果状态遗漏了影响未来的历史信息，即使转移表写得再完整，也只是精确求解了一个定义不充分的问题。动态规划能够保证求解过程正确，却不能替建模者保证 MDP 与现实一致。</p><h2 id="三、策略评估在计算什么" tabindex="-1">三、策略评估在计算什么 <a class="header-anchor" href="#三、策略评估在计算什么" aria-label="Permalink to &quot;三、策略评估在计算什么&quot;">​</a></h2><h3 id="_3-1-固定策略后只剩价值预测" tabindex="-1">3.1 固定策略后只剩价值预测 <a class="header-anchor" href="#_3-1-固定策略后只剩价值预测" aria-label="Permalink to &quot;3.1 固定策略后只剩价值预测&quot;">​</a></h3><p>给定策略 $\\pi(a|s)$ 后，动作选择概率已经确定。策略评估（Policy Evaluation，策略评估）要计算：从每个状态出发，之后一直遵循这套策略，能够获得多少期望折扣回报。</p><p>状态价值满足贝尔曼期望方程：</p><p>$$ V^\\pi(s)=\\sum_a\\pi(a|s)\\sum_{s&#39;}P(s&#39;|s,a)\\left[R(s,a,s&#39;)+\\gamma V^\\pi(s&#39;)\\right] $$</p><p>等式右侧包含当前策略选择动作的概率、环境转移概率、即时奖励和下一状态价值。它不是沿一条轨迹计算，而是对所有动作与后继状态取期望。</p><h3 id="_3-2-迭代评估从任意初值开始" tabindex="-1">3.2 迭代评估从任意初值开始 <a class="header-anchor" href="#_3-2-迭代评估从任意初值开始" aria-label="Permalink to &quot;3.2 迭代评估从任意初值开始&quot;">​</a></h3><p>如果暂时不知道真实价值，可以先把非终止状态价值初始化为零或其他有限值，再反复应用更新：</p><p>$$ V_{k+1}(s)\\leftarrow\\sum_a\\pi(a|s)\\sum_{s&#39;}P(s&#39;|s,a)\\left[R(s,a,s&#39;)+\\gamma V_k(s&#39;)\\right] $$</p><p>每次更新都使用上一轮价值估计。只要满足常见的有限折扣 MDP 条件，反复迭代会收敛到 $V^\\pi$。</p><p><img src="'+o+'" alt="策略评估的价值传播"></p><h3 id="_3-3-终止附近先获得有效价值" tabindex="-1">3.3 终止附近先获得有效价值 <a class="header-anchor" href="#_3-3-终止附近先获得有效价值" aria-label="Permalink to &quot;3.3 终止附近先获得有效价值&quot;">​</a></h3><p>在只有终点奖励的网格世界中，与终点直接相邻的状态最先感受到奖励。再下一轮更新中，这些状态的价值会影响更远状态。价值像波纹一样从有奖励的区域向外传播。</p><p>这里的“倒着传”不是时间真的逆向运行，而是贝尔曼关系让当前状态引用下一状态价值。只要后继价值改变，前驱状态在后续备份中就会受到影响。</p><h3 id="_3-4-收敛阈值控制停止条件" tabindex="-1">3.4 收敛阈值控制停止条件 <a class="header-anchor" href="#_3-4-收敛阈值控制停止条件" aria-label="Permalink to &quot;3.4 收敛阈值控制停止条件&quot;">​</a></h3><p>实践中通常记录一轮扫描前后价值的最大变化：</p><p>$$ \\Delta=\\max_s|V_{k+1}(s)-V_k(s)| $$</p><p>当 $\\Delta$ 小于预设阈值时停止。阈值越小，评估通常越精确，但计算量更大。停止阈值是数值求解条件，不是策略在真实任务中的成功标准。</p><h2 id="四、策略改进为什么能变好" tabindex="-1">四、策略改进为什么能变好 <a class="header-anchor" href="#四、策略改进为什么能变好" aria-label="Permalink to &quot;四、策略改进为什么能变好&quot;">​</a></h2><h3 id="_4-1-用当前价值向前看一步" tabindex="-1">4.1 用当前价值向前看一步 <a class="header-anchor" href="#_4-1-用当前价值向前看一步" aria-label="Permalink to &quot;4.1 用当前价值向前看一步&quot;">​</a></h3><p>完成策略评估后，可以计算在状态 $s$ 临时选择动作 $a$ 的一步前瞻价值：</p><p>$$ q_\\pi(s,a)=\\sum_{s&#39;}P(s&#39;|s,a)\\left[R(s,a,s&#39;)+\\gamma V^\\pi(s&#39;)\\right] $$</p><p>它比较的不是动作即时奖励，而是动作带来的即时奖励与后继长期价值。</p><h3 id="_4-2-贪心选择形成新策略" tabindex="-1">4.2 贪心选择形成新策略 <a class="header-anchor" href="#_4-2-贪心选择形成新策略" aria-label="Permalink to &quot;4.2 贪心选择形成新策略&quot;">​</a></h3><p>策略改进（Policy Improvement，策略改进）在每个状态选择使一步前瞻价值最大的动作：</p><p>$$ \\pi&#39;(s)\\in\\arg\\max_a q_\\pi(s,a) $$</p><p>根据策略改进定理，这个新策略不会比原策略更差。直觉上，原策略本来按某种概率选择动作；现在至少选择了其中长期评价最高的动作，因此价值不会下降。</p><h3 id="_4-3-贪心不等于只看眼前" tabindex="-1">4.3 贪心不等于只看眼前 <a class="header-anchor" href="#_4-3-贪心不等于只看眼前" aria-label="Permalink to &quot;4.3 贪心不等于只看眼前&quot;">​</a></h3><p>这里的 greedy（贪心）是对 $q_\\pi(s,a)$ 贪心，而 $q_\\pi$ 已经包含后继状态的长期价值。它不是看到当前奖励最大就立即选择。</p><p>这也是价值方法的关键：先把长期后果压缩进价值，再进行局部动作选择。若价值估计正确，局部最大化就能体现长期目标。</p><h3 id="_4-4-最优动作可能不唯一" tabindex="-1">4.4 最优动作可能不唯一 <a class="header-anchor" href="#_4-4-最优动作可能不唯一" aria-label="Permalink to &quot;4.4 最优动作可能不唯一&quot;">​</a></h3><p>多个动作可能得到相同最大值。此时可以任选一个形成确定性策略，也可以在最优动作之间随机化。算法实现若只使用 <code>argmax</code>，通常会由动作顺序决定平局选择，需要在可复现性分析中注意。</p><h2 id="五、策略迭代如何工作" tabindex="-1">五、策略迭代如何工作 <a class="header-anchor" href="#五、策略迭代如何工作" aria-label="Permalink to &quot;五、策略迭代如何工作&quot;">​</a></h2><h3 id="_5-1-评估与改进交替进行" tabindex="-1">5.1 评估与改进交替进行 <a class="header-anchor" href="#_5-1-评估与改进交替进行" aria-label="Permalink to &quot;5.1 评估与改进交替进行&quot;">​</a></h3><p>策略迭代由两个反复交替的阶段构成：</p><ul><li>策略评估：固定 $\\pi_k$，计算 $V^{\\pi_k}$。</li><li>策略改进：对 $V^{\\pi_k}$ 做一步前瞻，得到更贪心的 $\\pi_{k+1}$。</li></ul><p><img src="'+h+'" alt="策略迭代闭环"></p><p>只要改进后策略发生变化，就重新评估新策略。当所有状态的动作选择都不再变化时，策略稳定，有限 MDP 中可以得到最优策略。</p><h3 id="_5-2-精确评估不是唯一选择" tabindex="-1">5.2 精确评估不是唯一选择 <a class="header-anchor" href="#_5-2-精确评估不是唯一选择" aria-label="Permalink to &quot;5.2 精确评估不是唯一选择&quot;">​</a></h3><p>理论描述常把策略评估做到完全收敛，再进行策略改进。但实践中不一定需要每次都把评估误差降到极小。只进行有限轮评估也可能有效，这类方法称为广义策略迭代（Generalized Policy Iteration，广义策略迭代）的一种表现。</p><p>核心不是两个阶段必须严格分离，而是价值估计不断趋向当前策略的真实价值，策略又不断对当前价值变得更贪心。</p><h3 id="_5-3-策略迭代保留完整中间策略" tabindex="-1">5.3 策略迭代保留完整中间策略 <a class="header-anchor" href="#_5-3-策略迭代保留完整中间策略" aria-label="Permalink to &quot;5.3 策略迭代保留完整中间策略&quot;">​</a></h3><p>每次策略改进后，都有一套可执行的新策略。即使尚未到达最优，它也有明确行为含义。这个特点与价值迭代的中间价值传播有所不同。</p><h2 id="六、价值迭代省略了什么" tabindex="-1">六、价值迭代省略了什么 <a class="header-anchor" href="#六、价值迭代省略了什么" aria-label="Permalink to &quot;六、价值迭代省略了什么&quot;">​</a></h2><h3 id="_6-1-直接应用贝尔曼最优更新" tabindex="-1">6.1 直接应用贝尔曼最优更新 <a class="header-anchor" href="#_6-1-直接应用贝尔曼最优更新" aria-label="Permalink to &quot;6.1 直接应用贝尔曼最优更新&quot;">​</a></h3><p>价值迭代不把当前策略完整评估到收敛，而是直接更新：</p><p>$$ V_{k+1}(s)\\leftarrow\\max_a\\sum_{s&#39;}P(s&#39;|s,a)\\left[R(s,a,s&#39;)+\\gamma V_k(s&#39;)\\right] $$</p><p>每次备份都假设当前状态选择对现有价值最有利的动作。反复更新后，$V_k$ 逐渐逼近最优价值 $V^*$。</p><h3 id="_6-2-它像截断的策略评估" tabindex="-1">6.2 它像截断的策略评估 <a class="header-anchor" href="#_6-2-它像截断的策略评估" aria-label="Permalink to &quot;6.2 它像截断的策略评估&quot;">​</a></h3><p>价值迭代可以理解为：策略评估只做很少工作，就立即进行贪心改进，再继续传播价值。它把“评估”和“改进”压缩进一个贝尔曼最优备份。</p><p><img src="'+s+'" alt="策略迭代与价值迭代对比"></p><h3 id="_6-3-收敛后再提取策略" tabindex="-1">6.3 收敛后再提取策略 <a class="header-anchor" href="#_6-3-收敛后再提取策略" aria-label="Permalink to &quot;6.3 收敛后再提取策略&quot;">​</a></h3><p>得到近似最优价值后，可以按下式提取策略：</p><p>$$ \\pi(s)\\in\\arg\\max_a\\sum_{s&#39;}P(s&#39;|s,a)\\left[R(s,a,s&#39;)+\\gamma V(s&#39;)\\right] $$</p><p>价值迭代中间的 $V_k$ 不一定对应某个已被完整评估的策略，因此不要把每轮中间价值都解释成当前策略的准确表现。</p><h2 id="七、网格世界里价值怎样传播" tabindex="-1">七、网格世界里价值怎样传播 <a class="header-anchor" href="#七、网格世界里价值怎样传播" aria-label="Permalink to &quot;七、网格世界里价值怎样传播&quot;">​</a></h2><h3 id="_7-1-建立最小环境" tabindex="-1">7.1 建立最小环境 <a class="header-anchor" href="#_7-1-建立最小环境" aria-label="Permalink to &quot;7.1 建立最小环境&quot;">​</a></h3><p>假设智能体位于一个有限网格，可以向上、下、左、右移动。到达终点得到正奖励，撞到障碍或边界产生代价，其他移动给出小的时间成本。</p><p>转移可以是确定性的，也可以加入打滑概率。若动作“向上”有一定概率偏向左右，动态规划会把所有分支按概率加权，而不是只计算理想移动。</p><h3 id="_7-2-价值从奖励边界向外扩散" tabindex="-1">7.2 价值从奖励边界向外扩散 <a class="header-anchor" href="#_7-2-价值从奖励边界向外扩散" aria-label="Permalink to &quot;7.2 价值从奖励边界向外扩散&quot;">​</a></h3><p>初始化时所有普通状态价值相同。终点附近状态经过备份后率先变大，因为它们能在较少步数内获得奖励。更远状态随后引用这些新价值，逐渐形成指向终点的价值梯度。</p><h3 id="_7-3-折扣与步进代价改变路径偏好" tabindex="-1">7.3 折扣与步进代价改变路径偏好 <a class="header-anchor" href="#_7-3-折扣与步进代价改变路径偏好" aria-label="Permalink to &quot;7.3 折扣与步进代价改变路径偏好&quot;">​</a></h3><p>较小的折扣因子会快速削弱远处终点价值，使智能体更偏好短期收益。每步负奖励会鼓励更短路径；若危险区域惩罚不够大，最优路径可能从高风险捷径穿过。</p><p>因此，价值传播不仅“找到路”，还忠实反映奖励设计。奖励定义错了，动态规划会高效地求出错误目标下的最优路径。</p><h3 id="_7-4-障碍背后传播需要更多扫描" tabindex="-1">7.4 障碍背后传播需要更多扫描 <a class="header-anchor" href="#_7-4-障碍背后传播需要更多扫描" aria-label="Permalink to &quot;7.4 障碍背后传播需要更多扫描&quot;">​</a></h3><p>每轮同步更新只能把价值信息沿状态转移关系传播有限距离。长走廊、障碍绕行和稀疏奖励会增加传播轮数。优先更新重要状态或使用更合理的更新顺序，可以加快收敛。</p><h2 id="八、同步更新与异步更新" tabindex="-1">八、同步更新与异步更新 <a class="header-anchor" href="#八、同步更新与异步更新" aria-label="Permalink to &quot;八、同步更新与异步更新&quot;">​</a></h2><h3 id="_8-1-同步更新使用上一轮副本" tabindex="-1">8.1 同步更新使用上一轮副本 <a class="header-anchor" href="#_8-1-同步更新使用上一轮副本" aria-label="Permalink to &quot;8.1 同步更新使用上一轮副本&quot;">​</a></h3><p>同步更新（Synchronous Update，同步更新）先读取旧价值 $V_k$ 计算所有新值，整轮结束后再替换为 $V_{k+1}$。结果容易分析，也便于并行，但需要保存两份价值或确保读写隔离。</p><h3 id="_8-2-异步更新立即使用新值" tabindex="-1">8.2 异步更新立即使用新值 <a class="header-anchor" href="#_8-2-异步更新立即使用新值" aria-label="Permalink to &quot;8.2 异步更新立即使用新值&quot;">​</a></h3><p>异步更新（Asynchronous Update，异步更新）某个状态更新后，后续状态可以立即使用这个新值。合适的扫描顺序可能显著加快传播。</p><p>但异步不等于任意漏掉状态。为了保证常见条件下收敛，各状态需要被持续更新。实现中还要避免并发写入造成不可控的数据竞争。</p><h3 id="_8-3-更新顺序体现计算资源分配" tabindex="-1">8.3 更新顺序体现计算资源分配 <a class="header-anchor" href="#_8-3-更新顺序体现计算资源分配" aria-label="Permalink to &quot;8.3 更新顺序体现计算资源分配&quot;">​</a></h3><p>如果知道哪些状态的贝尔曼误差更大，可以优先更新它们，这与 prioritized sweeping（优先扫描）等思想相关。它说明动态规划不只有公式，状态更新顺序同样影响计算效率。</p><h2 id="九、策略迭代还是价值迭代" tabindex="-1">九、策略迭代还是价值迭代 <a class="header-anchor" href="#九、策略迭代还是价值迭代" aria-label="Permalink to &quot;九、策略迭代还是价值迭代&quot;">​</a></h2><h3 id="_9-1-策略迭代的特点" tabindex="-1">9.1 策略迭代的特点 <a class="header-anchor" href="#_9-1-策略迭代的特点" aria-label="Permalink to &quot;9.1 策略迭代的特点&quot;">​</a></h3><p>策略迭代每次都得到一套明确策略，评估阶段可能消耗较多计算，但策略改进次数通常较少。它适合希望跟踪中间策略、策略评估相对容易的场景。</p><h3 id="_9-2-价值迭代的特点" tabindex="-1">9.2 价值迭代的特点 <a class="header-anchor" href="#_9-2-价值迭代的特点" aria-label="Permalink to &quot;9.2 价值迭代的特点&quot;">​</a></h3><p>价值迭代每次扫描更直接，将最优选择放入更新，避免把每个中间策略完全评估。它可能需要更多价值传播轮次，但单轮结构简单。</p><h3 id="_9-3-选择取决于问题结构" tabindex="-1">9.3 选择取决于问题结构 <a class="header-anchor" href="#_9-3-选择取决于问题结构" aria-label="Permalink to &quot;9.3 选择取决于问题结构&quot;">​</a></h3><p>不存在脱离任务规模和求解精度的绝对胜负。状态数量、动作数量、转移稀疏性、评估求解方式、停止阈值和更新顺序都会影响实际计算成本。</p><p>教学中更重要的是看清共同点：二者都依赖完整模型，都使用贝尔曼备份，都在价值预测与策略改进之间建立联系。</p><h2 id="十、动态规划与强化学习的边界" tabindex="-1">十、动态规划与强化学习的边界 <a class="header-anchor" href="#十、动态规划与强化学习的边界" aria-label="Permalink to &quot;十、动态规划与强化学习的边界&quot;">​</a></h2><h3 id="_10-1-动态规划拥有完整模型" tabindex="-1">10.1 动态规划拥有完整模型 <a class="header-anchor" href="#_10-1-动态规划拥有完整模型" aria-label="Permalink to &quot;10.1 动态规划拥有完整模型&quot;">​</a></h3><p>对每个状态动作对，动态规划知道所有后继状态、概率和奖励。它可以计算精确期望，不必真的与环境反复试错。</p><h3 id="_10-2-强化学习通常只有样本" tabindex="-1">10.2 强化学习通常只有样本 <a class="header-anchor" href="#_10-2-强化学习通常只有样本" aria-label="Permalink to &quot;10.2 强化学习通常只有样本&quot;">​</a></h3><p>真实任务中，智能体采取一次动作，只观察到一个下一状态和一次奖励。蒙特卡洛方法从完整轨迹估计回报，时序差分方法用采样转移进行自举，Q-learning 则用样本近似贝尔曼最优更新。</p><h3 id="_10-3-共同骨架是贝尔曼关系" tabindex="-1">10.3 共同骨架是贝尔曼关系 <a class="header-anchor" href="#_10-3-共同骨架是贝尔曼关系" aria-label="Permalink to &quot;10.3 共同骨架是贝尔曼关系&quot;">​</a></h3><p>动态规划做完整宽度的期望备份，强化学习往往做基于样本的备份。信息来源不同，更新目标却都来自“即时奖励＋后继价值”。</p><p>这也是为什么先学动态规划有价值：它提供一份已知模型下的标准答案，后续算法可以被理解为在模型未知、样本有限条件下逼近同一个价值关系。</p><h2 id="十一、放到自动驾驶里要警惕什么" tabindex="-1">十一、放到自动驾驶里要警惕什么 <a class="header-anchor" href="#十一、放到自动驾驶里要警惕什么" aria-label="Permalink to &quot;十一、放到自动驾驶里要警惕什么&quot;">​</a></h2><h3 id="_11-1-完整交通转移模型通常不存在" tabindex="-1">11.1 完整交通转移模型通常不存在 <a class="header-anchor" href="#_11-1-完整交通转移模型通常不存在" aria-label="Permalink to &quot;11.1 完整交通转移模型通常不存在&quot;">​</a></h3><p>自动驾驶可以近似知道自车动力学，却很难精确知道每个交通参与者在所有状态动作下的反应分布。直接宣称用价值迭代求出真实交通最优策略，往往隐含了过强模型假设。</p><h3 id="_11-2-离散状态会迅速膨胀" tabindex="-1">11.2 离散状态会迅速膨胀 <a class="header-anchor" href="#_11-2-离散状态会迅速膨胀" aria-label="Permalink to &quot;11.2 离散状态会迅速膨胀&quot;">​</a></h3><p>自车速度、相对距离、相对速度、道路曲率、邻车状态和执行器状态一旦离散组合，状态数量会呈乘法增长。这就是 curse of dimensionality（维数灾难）。</p><p><img src="'+n+'" alt="从小型网格到自动驾驶状态爆炸"></p><h3 id="_11-3-模型误差会传播到策略" tabindex="-1">11.3 模型误差会传播到策略 <a class="header-anchor" href="#_11-3-模型误差会传播到策略" aria-label="Permalink to &quot;11.3 模型误差会传播到策略&quot;">​</a></h3><p>动态规划会反复使用转移模型。若模型低估邻车封堵概率或制动延迟，价值更新会系统性高估激进行为。求解精度越高，不代表现实可靠性越高。</p><h3 id="_11-4-安全不能只靠期望价值" tabindex="-1">11.4 安全不能只靠期望价值 <a class="header-anchor" href="#_11-4-安全不能只靠期望价值" aria-label="Permalink to &quot;11.4 安全不能只靠期望价值&quot;">​</a></h3><p>贝尔曼期望会按概率平均不同未来。低概率但严重的碰撞风险可能被平均收益掩盖。安全关键任务还需要约束、风险度量、最坏情况分析和备份控制器。</p><h2 id="十二、实现动态规划最容易犯的错误" tabindex="-1">十二、实现动态规划最容易犯的错误 <a class="header-anchor" href="#十二、实现动态规划最容易犯的错误" aria-label="Permalink to &quot;十二、实现动态规划最容易犯的错误&quot;">​</a></h2><h3 id="_12-1-奖励时间索引错位" tabindex="-1">12.1 奖励时间索引错位 <a class="header-anchor" href="#_12-1-奖励时间索引错位" aria-label="Permalink to &quot;12.1 奖励时间索引错位&quot;">​</a></h3><p>要明确奖励属于当前状态、当前动作还是到达下一状态后的转移。公式与代码必须使用同一约定，否则终点奖励可能提前或延后传播。</p><h3 id="_12-2-终止状态继续自举" tabindex="-1">12.2 终止状态继续自举 <a class="header-anchor" href="#_12-2-终止状态继续自举" aria-label="Permalink to &quot;12.2 终止状态继续自举&quot;">​</a></h3><p>任务真正终止后通常没有后续价值。若仍把终止状态价值加进目标，会重复计算终止之后并不存在的回报。</p><h3 id="_12-3-原地更新却声称同步" tabindex="-1">12.3 原地更新却声称同步 <a class="header-anchor" href="#_12-3-原地更新却声称同步" aria-label="Permalink to &quot;12.3 原地更新却声称同步&quot;">​</a></h3><p>边扫描边覆盖价值会变成异步更新。它不一定错误，但结果与收敛速度可能不同，必须与设计和验证描述一致。</p><h3 id="_12-4-只检查价值变化不检查策略" tabindex="-1">12.4 只检查价值变化不检查策略 <a class="header-anchor" href="#_12-4-只检查价值变化不检查策略" aria-label="Permalink to &quot;12.4 只检查价值变化不检查策略&quot;">​</a></h3><p>策略迭代需要判断策略是否稳定；价值迭代需要在停止后重新提取并验证策略。价值变化小不代表实现中的动作选择、边界处理和奖励索引一定正确。</p><h3 id="_12-5-用单个地图证明算法普适" tabindex="-1">12.5 用单个地图证明算法普适 <a class="header-anchor" href="#_12-5-用单个地图证明算法普适" aria-label="Permalink to &quot;12.5 用单个地图证明算法普适&quot;">​</a></h3><p>一个确定性小网格只能验证基本数据流。还应检查随机转移、不同折扣、奖励尺度、障碍布局、平局动作和不可达状态。</p><h2 id="十三、最小验证清单" tabindex="-1">十三、最小验证清单 <a class="header-anchor" href="#十三、最小验证清单" aria-label="Permalink to &quot;十三、最小验证清单&quot;">​</a></h2><ul><li>转移概率对每个状态动作对是否归一化。</li><li>终止状态的价值和自举规则是否明确。</li><li>同步或异步更新是否与实现一致。</li><li>策略评估结果是否满足贝尔曼残差阈值。</li><li>策略改进后价值是否没有下降。</li><li>策略迭代停止时策略是否稳定。</li><li>价值迭代停止后提取策略是否能够完成任务。</li><li>随机转移下是否按全部后继概率求期望。</li><li>不同初始化是否收敛到一致结果。</li><li>小型环境结果是否能通过手算或穷举交叉验证。</li></ul><p>动态规划最适合作为“可核对的算法实验”。模型已知、状态有限，许多结果能够手算，这为后续更复杂的采样学习提供可靠基线。</p><h2 id="十四、接下来进入蒙特卡洛方法" tabindex="-1">十四、接下来进入蒙特卡洛方法 <a class="header-anchor" href="#十四、接下来进入蒙特卡洛方法" aria-label="Permalink to &quot;十四、接下来进入蒙特卡洛方法&quot;">​</a></h2><p>动态规划最大的限制已经很清楚：它需要完整环境模型。现实中，我们通常拿不到 $P(s&#39;|s,a)$，只能通过一次次交互观察轨迹。</p><p>下一篇将进入蒙特卡洛方法（Monte Carlo Methods，蒙特卡洛方法），解释怎样不依赖转移模型，直接用完整回合的真实回报估计价值；也会讨论首次访问、每次访问、增量平均和高方差问题。</p><h2 id="十五、结语" tabindex="-1">十五、结语 <a class="header-anchor" href="#十五、结语" aria-label="Permalink to &quot;十五、结语&quot;">​</a></h2><p>动态规划让长期价值变得可计算：策略评估回答“这套策略有多好”，策略改进回答“怎样做得更好”，策略迭代在两者之间循环，价值迭代则把循环压缩进最优备份。</p><p>价值从终点向外传播，不是神秘的反向时间过程，而是每个状态持续吸收后继状态的信息。一次备份只看一步，但反复备份最终能够表达很长的未来。</p><p>它的边界同样清晰：模型必须已知，状态动作需要可处理，求解结果只对当前模型、奖励和约束成立。理解这些边界，才能看懂强化学习如何从“遍历完整模型”走向“使用有限样本学习”。</p><h2 id="十六、资料来源" tabindex="-1">十六、资料来源 <a class="header-anchor" href="#十六、资料来源" aria-label="Permalink to &quot;十六、资料来源&quot;">​</a></h2><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter2/chapter2.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第 2 章“马尔可夫决策过程”原始文档</a></p><p><a href="https://www.davidsilver.uk/wp-content/uploads/2020/03/DP.pdf" target="_blank" rel="noreferrer">David Silver 强化学习课程动态规划讲义</a></p><p><a href="https://spinningup.openai.com/en/latest/spinningup/rl_intro.html" target="_blank" rel="noreferrer">OpenAI Spinning Up（OpenAI 强化学习入门资料）价值函数与贝尔曼方程</a></p><p><a href="https://mitpress.mit.edu/9780262039246/reinforcement-learning/" target="_blank" rel="noreferrer">MIT Press（麻省理工学院出版社）《Reinforcement Learning: An Introduction》2nd edition（第 2 版）页面</a></p><blockquote><p>版权说明：本文基于公开资料重新组织，示意图均为本篇原创绘制，不复刻原教程或课程讲义插图。</p></blockquote>',144)])])}const k=e(p,[["render",d]]);export{f as __pageData,k as default};
